month = None
months = [
    "jan",
    "feb",
    "mar",
    "apr",
    "maj",
    "jun",
    "jul",
    "aug",
    "sep",
    "okt",
    "nov",
    "dec",
]

def time_to_number(text):
    if not text:
        return None
    hours, minutes = list(map(int, text.split(":")))
    return (60 * hours + minutes) / (60 * 24)

result = {}

for line in text.splitlines():
    args = line.split("\t")
    (
        date,
        sunrise,
        sunset,
        _,
        _,
        zenit,
        astronomical_morning,
        astronomical_evening,
        nautical_morning,
        nautical_evening,
        civil_morning,
        civil_evening,
        night_start,
        night_end,
        blue_morning,
        blue_evening,
        gold_morning,
        gold_evening,
    ) = args

    try:
        int(date)
    except:
        month = months.index(date) + 1
        continue

    date = f"{int(date)}/{month}"

    astronomical_dawn = ""
    if "*" not in astronomical_morning:
        astronomical_dawn = astronomical_morning.split(" – ")[0]

    nautical_dawn = ""
    if "*" not in nautical_morning:
        nautical_dawn = nautical_morning.split(" – ")[0]

    civil_dawn = civil_morning.split(" – ")[0]

    twilight_dawn, blue_dawn = map(str.strip, blue_morning.split("–"))

    gold_dawn = gold_morning.split(" – ")[1]

    gold_dusk = gold_evening.split(" – ")[0]

    twilight_dusk, blue_dusk = map(str.strip, blue_evening.split("–"))

    civil_dusk = civil_evening.split(" – ")[1]

    nautical_dusk = ""
    if "*" not in nautical_evening:
        nautical_dusk = nautical_evening.split(" – ")[1]

    astronomical_dusk = ""
    if "*" not in astronomical_evening:
        astronomical_dusk = astronomical_evening.split(" – ")[1]

    result[date] = [
        time_to_number(astronomical_dawn),
        time_to_number(nautical_dawn),
        time_to_number(twilight_dawn),
        time_to_number(civil_dawn),
        time_to_number(blue_dawn),
        time_to_number(sunrise),
        time_to_number(gold_dawn),
        time_to_number(zenit),
        time_to_number(gold_dusk),
        time_to_number(sunset),
        time_to_number(blue_dusk),
        time_to_number(civil_dusk),
        time_to_number(twilight_dusk),
        time_to_number(nautical_dusk),
        time_to_number(astronomical_dusk),
    ]

print(json.dumps(result))

